package com.ips.ui;
import com.ips.dao.FeatureDAO;import com.ips.model.*;import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;import java.sql.SQLException;import java.util.*;
public class BookmarksFrame extends JFrame{
 private final User user;private final DefaultListModel<Question> model=new DefaultListModel<>();private final JList<Question> list=new JList<>(model);
 public BookmarksFrame(User user){this.user=user;UIStyle.configureFrame(this,"Saved Questions",760,520);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel root=new JPanel(new BorderLayout(12,12));root.setBackground(UIStyle.BACKGROUND);root.setBorder(new EmptyBorder(22,24,22,24));root.add(UIStyle.heading("Saved questions"),BorderLayout.NORTH);list.setCellRenderer((l,v,i,s,f)->{JLabel x=new JLabel("  ["+v.getCategory()+"] "+v.getQuestionText());x.setOpaque(true);x.setBorder(new EmptyBorder(12,10,12,10));x.setBackground(s?new Color(67,78,112):UIStyle.PANEL);x.setForeground(UIStyle.TEXT);return x;});root.add(new JScrollPane(list),BorderLayout.CENTER);JPanel buttons=new JPanel(new FlowLayout(FlowLayout.RIGHT));buttons.setBackground(UIStyle.BACKGROUND);JButton revise=UIStyle.primaryButton("Practice saved questions"),remove=UIStyle.primaryButton("Remove bookmark"),refresh=UIStyle.linkButton("Refresh");revise.addActionListener(e->practice());remove.addActionListener(e->remove());refresh.addActionListener(e->load());buttons.add(refresh);buttons.add(remove);buttons.add(revise);root.add(buttons,BorderLayout.SOUTH);setContentPane(root);load();}
 private void load(){try{model.clear();for(Question q:new FeatureDAO().bookmarks(user.getId()))model.addElement(q);}catch(SQLException e){error(e);}}
 private void remove(){Question q=list.getSelectedValue();if(q==null)return;try{new FeatureDAO().toggleBookmark(user.getId(),q.getId());load();}catch(SQLException e){error(e);}}
 private void practice(){if(model.isEmpty()){JOptionPane.showMessageDialog(this,"No saved questions yet. Bookmark questions while practicing.");return;}java.util.List<Question> qs=Collections.list(model.elements());new PracticeFrame(user,"Saved Questions",qs).setVisible(true);}
 private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Database error",JOptionPane.ERROR_MESSAGE);}
}
